head.script:
scwin.strNameSpace = 'xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:xf="http://www.w3.org/2002/xforms"';

scwin.onpageload = async function () {
    // 화면 로딩(onpageload) 중 editor 를 자식으로 가진 generator 와 editor 를 dynamicCreate 로 생성
    await scwin.createComp("A", grp_onpageload);
    scwin.printResult("A");
};

// editor 를 자식으로 가진 generator + 단독 editor 를 dynamicCreate 로 생성 후 generator 자식 생성
scwin.createComp = async function (prefix, parent) {
    let strGenerator = '<w2:generator ' + scwin.strNameSpace + ' id="gen' + prefix + '" style="width:420px;">'
                     + '<w2:editor id="genChild" style="width:400px; height:200px;"></w2:editor>'
                     + '</w2:generator>';
    scwin["gen" + prefix] = await $p.dynamicCreate("gen" + prefix, "generator", strGenerator, parent);

    let strEditor = '<w2:editor ' + scwin.strNameSpace + ' id="editor' + prefix + '" style="width:400px; height:200px;"></w2:editor>';
    await $p.dynamicCreate("editor" + prefix, "editor", strEditor, parent);

    await scwin["gen" + prefix].insertChildAsync(0);
};

// 각 editor 가 화면에 그려졌는지(편집 영역 생성 여부) 출력
scwin.printResult = function (prefix) {
    let standalone = document.querySelector("#" + $p.getComponentById("editor" + prefix).id + " .cke_contents") ? "O" : "X";
    let genChild = document.querySelector("#" + scwin["gen" + prefix].id + " .cke_contents") ? "O" : "X";
    scwin.setReturnValue("[" + prefix + "] editor 렌더 : " + standalone + " / generator 자식 editor 렌더 : " + genChild);
};

scwin.btn_create_onclick = async function (e) {
    if (typeof scwin.genB !== "undefined") {
        return;
    }
    await scwin.createComp("B", grp_onclick);
    scwin.printResult("B");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
